(() => {
  const TRANSLATIONS = { uz: {"meta": {"title": "Pakhtachi Stone Group — Kimyo zavodlari qurilishi va montaji", "description": "Kimyo sanoati obyektlarini to'liq tsiklda quramiz: uskuna montaji, kislota quvurlari, futerovka, kimyoviy chidamli qoplama va izolyatsiya. O'zbekiston bo'ylab."}, "aria": {"brand": "Pakhtachi Stone Group — bosh sahifa", "nav": "Asosiy navigatsiya", "burgerOpen": "Menyuni ochish", "lightboxClose": "Yopish", "lightboxPrev": "Oldingi", "lightboxNext": "Keyingi"}, "brand": {"tagline": "Sanoat qurilishi & montaj"}, "nav": {"about": "Biz haqimizda", "services": "Xizmatlar", "stages": "Bosqichlar", "projects": "Obyektlar", "faq": "FAQ", "contact": "Aloqa", "cta": "Smeta olish"}, "hero": {"kicker": "O'zbekiston · Samarqand · 2016-yildan beri", "line1": "Kimyo zavodlari", "line2pre": "qurilishi va ", "line2em": "montaji", "line3": "loyihadan ishga tushirishgacha", "lead": "Reaktor va kolonnalar, kislotaga chidamli quvur tizimlari, rezervuar montaji va futerovka, argon payvandlash, kimyoviy chidamli qoplamalar va izolyatsiya — kimyo zavodi uchun kerak bo'lgan hamma ish bitta pudratchida.", "cta1": "Loyihani hisoblab berish", "cta2": "Xizmatlar bilan tanishish", "stat1": "yildan beri sanoat montajida", "stat2": "xodim — o'z shtatimizda", "stat3": "muhandis va texnik mutaxassis", "stat4": "gacha energiya tejamkorligi"}, "about": {"label": "01 — Biz haqimizda", "h2a": "Sanoat obyektlari uchun", "h2b": "to'liq tsiklli pudratchi", "lead": "«Pakhtachi Stone Group» — sanoat obyektlarida qurilish-montaj ishlarini bajaruvchi pudrat tashkiloti. Metallokonstruksiya montaji, payvandlash, quvur tizimlari, rezervuar va uskuna montaji, antikorroziy himoya, izolyatsiya va lesa ishlari — bularning barchasi bizning kundalik ishimiz.", "p1": "Bugun biz kuchimizni ongli ravishda <b>kimyo sanoati obyektlariga</b> yo'naltirmoqdamiz. Sababi oddiy: kimyo zavodi talab qiladigan ishlar — aynan biz bajaradigan ishlar, faqat ular yuqori talablar va agressiv muhit sharoitida bajariladi. Shu yo'nalish bo'yicha jamoamizni tayyorlayapmiz, material va texnologiya bazasini shakllantiryapmiz.", "p2": "Texnik izolyatsiya sohasida esa kompaniya sanoat qurilmalari uchun issiqlik, sovuq, tovush va yong'in himoyasidan tortib gaz turbinalari uchun maxsus izolyatsiyagacha bo'lgan barcha xizmatlarni taklif etadi. Yevropa va MDH davlatlaridagi hamkorlar bilan ishlaymiz.", "principle": "Tamoyilimiz: obyekt vaqtida, loyiha bo'yicha va <em>xavfsiz</em> topshirilishi kerak.", "photoAlt": "Texnologik quvurlar izolyatsiyasi — Pakhtachi Stone Group obyekti", "points": ["Sanoat qurilishida ishonchli hamkor", "Xalqaro standartlarga mos yuqori sifatli xizmatlar", "Samaradorlik, energiya tejash va xavfsizlikni oshiruvchi yechimlar", "Bitta shartnoma — bitta javobgarlik"]}, "services": {"label": "02 — Xizmatlar", "h2a": "Kimyo zavodi uchun kerak bo'lgan", "h2b": "hamma ish — bitta pudratchida", "items": [{"name": "Quvur o'tkazgichlar montaji", "tag": "Agressiv muhitlar", "body": "Kimyo zavodida quvur tizimi eng zaif nuqta: materiali noto'g'ri tanlangan bitta uchastka butun liniyani to'xtatadi. Biz quvurni muhitga, haroratga va konsentratsiyaga qarab tanlaymiz.", "li": ["Kislota va ishqor quvurlari (H₂SO₄, HNO₃, H₃PO₄, NaOH)", "Nerjaveyka tizimlari — AISI 304, 316L, 321, duplex", "Polimer quvurlar: PP, PVDF, PE100, PVX", "Futerovkalangan quvurlar (rezina, ftoroplast, emal)", "Zapor-tartibga soluvchi armatura montaji", "Gidravlik va pnevmatik sinov, passivatsiya, markirovka"]}, {"name": "Uskunalar montaji", "tag": "Reaktor · Kolonna", "body": "Reaktor, kolonna, issiqlik almashtirgich — kimyo zavodining yuragi. O'rnatish aniqligi millimetrlarda o'lchanadi, ko'tarish sxemasi oldindan ishlab chiqiladi va tasdiqlanadi.", "li": ["Reaktor, kolonna, absorber va skrubberlarni o'rnatish", "Issiqlik almashtirgich, sushilka, granulyator, filtr", "Nasos, kompressor va gaz tozalash uskunalari", "Lazerli asbob bilan sentrovka, ankerlash va podliv", "Obvyazka, KIPiA ulash, sinash va ishga tushirish", "To'xtatish remonti oynasida ishlash tajribasi"]}, {"name": "Rezervuarlar montaji", "tag": "RVS · RGS", "body": "Kislota, ishqor va reagent saqlash sig'imi — bosim, agressiv muhit va ekologik xavf birlashgan obyekt. Payvand choki ham, ichki qoplama ham bir xil darajada muhim.", "li": ["Vertikal va gorizontal po'lat rezervuarlar (RVS, RGS)", "Nerjaveykadan sig'imlar, mikser va reaktorlar", "Polipropilen va shishaplastik (FRP/GRP) sig'imlar", "Ichki futerovka: gummirovka, ftoroplast, kislotaga chidamli g'isht", "Germetiklik sinovi, uchqun bilan qoplama nazorati", "Tozalash, remont, tubini va devor poyasini almashtirish"]}, {"name": "Metallokonstruksiyalar", "tag": "Ishlab chiqarish + montaj", "body": "Kimyo zavodida metall karkas doimo agressiv atmosferada ishlaydi. Konstruksiyani nafaqat mustahkam, balki C5/CX darajada himoyalangan holda topshiramiz.", "li": ["Sanoat binolari va sexlar karkasi", "Apparatlar uchun etajerka, quvur estakadalari", "Xizmat maydonchalari, zinapoya, ograjdeniya", "Bunker, silos va konveyer galereyalari", "Nerjaveyka va alyuminiy konstruksiyalar", "Geodezik nazorat bilan montaj"]}, {"name": "Argon payvandlash (TIG)", "tag": "Nerjaveyka · Po'lat", "body": "Mas'uliyatli liniyalarda ildiz chokini argonda, to'ldirishni elektrod yoki yarim avtomat bilan bajaramiz — chok ichkaridan silliq chiqadi, oqim buzilmaydi.", "li": ["AISI 304, 316L, 321, duplex payvandlash", "Ichkariga argon puflash (podduv) bilan ildiz choki", "Alyuminiy, titan, mis va maxsus qotishmalar", "Choklarni travleniye va passivatsiya qilish", "Impuls (KIPiA) liniyalari — to'liq argonda", "Attestatsiyadan o'tgan payvandchilar"]}, {"name": "Elektr payvandlash", "tag": "MMA · MIG/MAG", "body": "Har bir mas'uliyatli chok raqamlanadi va payvandchiga biriktiriladi, VIK o'tkaziladi, talab bo'lsa — buzmaydigan nazorat (RK/UZK).", "li": ["Qo'lda dugali payvandlash (MMA/RDS)", "Yarim avtomat payvandlash (MIG/MAG)", "Balandlikda montaj payvandlashi", "Qalin devorli apparatlarni ko'p qatlamli payvandlash", "Korroziyaga uchragan uchastkalarni tiklash", "Ex-zonalarda olovli ishlar — naryad-dopusk bilan"]}, {"name": "Peskostruy tozalash", "tag": "Sa 2½ · ISO 8501", "body": "Bo'yoq va futerovkaning 80% muvaffaqiyati — bu tozalash. Agressiv muhit har qanday zaif adgeziyani bir necha oyda ochib tashlaydi.", "li": ["Sa 2 — Sa 2½ — Sa 3 darajasigacha tozalash", "Rezervuar ichi va tashqarisini futerovkaga tayyorlash", "Beton yuzalarni tozalash", "Nerjaveyka uchun temirsiz abraziv", "Rz g'adir-budurlik, chang va tuz qoldiqlari nazorati", "Metall harorati — shabnam nuqtasidan kamida 3°C yuqori"]}, {"name": "Kimyoviy chidamli qoplamalar", "tag": "C5-I / CX", "body": "Kimyo zavodi atmosferasi ISO 12944 bo'yicha odatda C5-I yoki CX kategoriyaga kiradi — eng og'ir sharoit. Bu yerda oddiy emal ishlamaydi.", "li": ["Sink grunt + epoksid + poliuretan tizimlari", "Vinilefir, epoksid-fenol, novolak qoplamalar", "Rezervuarlarni ichki qoplash", "Issiqlikka chidamli qoplamalar (200–600°C)", "Kimyoviy chidamli sanoat pollari", "DFT nazorati va uchqun defektoskopiyasi"]}, {"name": "Sanoat izolyatsiyasi", "tag": "Issiqlik · Sovuq · CUI", "body": "Energiya tejash, texnologik rejim, xodimlarni himoya qilish — va metallni izolyatsiya ostidagi korroziyadan (CUI) saqlash. Turbina izolyatsiyasi bo'yicha alohida tajribamiz bor.", "li": ["Quvur, reaktor va rezervuar izolyatsiyasi", "Gaz va bug' turbinalari uchun matras izolyatsiya", "Sovuq izolyatsiya: ammiak, freon liniyalari — bug' to'sig'i bilan", "Materiallar: bazalt vata, PPU, foamglass, keramik vata", "Qoplama qatlam: o'z stanogimizda o'lchov bo'yicha", "Elektr isitish (obogrev) va sovuqdan himoya tizimlari"]}, {"name": "Sanoat lesa montaji", "tag": "Montaj + ijara", "body": "Sanoat, maxsus va fasad lesalarining to'liq turlarini taklif qilamiz — alohida obyektlar, yirik loyihalar va uzoq muddatli shartnomalar uchun.", "li": ["Ramali, xomutli, klinovoy va modulli tizimlar", "Reaktor, kolonna va pech atrofida lesa", "Osma lesa va konsolli maydonchalar", "Yuk ko'targichlar — 2 000 kg gacha, 120 m gacha", "Lesa ijarasi — montaj va demontaj bilan", "Har bir lesa birka bilan qabul qilinadi"]}, {"name": "Kislotaga chidamli futerovka", "tag": "Plitka · G'isht", "body": "Yuqori konsentratsiya, harorat va mexanik yuk bo'lgan joyda plitka-g'isht futerovkasi eng ishonchli yechim — u o'nlab yillar xizmat qiladi. Devorlarga ham, eng og'ir sharoitdagi tag qismiga ham teramiz.", "li": ["Kislota rezervuarlari ichki futerovkasi", "Neytralizatsiya vannalari, priyomnik va zumpflar", "Diabaz plitka, KKG, shamot va uglerodli g'isht", "Silikat, furan, epoksid, vinilefir zamazkalari", "Germetik podsloy: gummirovka yoki epoksid bariyer", "Uchqun/vakuum nazorati, suv bilan sinov"]}]}, "stages": {"label": "03 — Qurilish bosqichlari", "h2a": "Obyektni texnologik zanjir", "h2b": "sifatida qabul qilamiz", "items": [{"title": "Loyiha va tayyorgarlik", "desc": "Obyektni ko'rish, muhitlar ro'yxatini o'rganish, materiallarni moslab tanlash, smeta va grafik."}, {"title": "Poydevor va yer osti qismi", "desc": "Fundament va ankerlar, kislotaga chidamli poddonlar, drenaj va oqava tizimi."}, {"title": "Metall karkas", "desc": "Kolonna va ferma montaji, quvur estakadalari, etajerka va maydonchalar."}, {"title": "Uskunalar montaji", "desc": "Reaktor, kolonna, issiqlik almashtirgich, nasos va kompressorlar. Aniq sentrovka."}, {"title": "Quvur tizimlari", "desc": "Har bir muhit uchun o'z liniyasi. Armatura, kompensator, sinov va markirovka."}, {"title": "Himoya qatlamlari", "desc": "Futerovka, antikorroziy tizim, issiqlik va sovuq izolyatsiyasi, CUI himoyasi."}, {"title": "Sinov va topshirish", "desc": "Gidravlik va pnevmatik sinov, yuvish, bo'sh yurishda sinash, ijro hujjatlari."}]}, "industries": {"label": "04 — Yo'nalishlar", "h2a": "Kimyo sanoatining qaysi", "h2b": "yo'nalishlarida ishlaymiz", "items": [{"title": "Mineral o'g'itlar", "desc": "ammiak, karbamid, selitra, ammofos, superfosfat"}, {"title": "Kislotalar", "desc": "oltingugurt, azot, fosfor kislotasi qurilmalari"}, {"title": "Xlor-ishqor va soda", "desc": "ishlab chiqarish qurilmalari"}, {"title": "Polimerlar", "desc": "polietilen, polipropilen, PVX, granula liniyalari"}, {"title": "Neft-kimyo", "desc": "gaz qayta ishlash, metanol, erituvchilar"}, {"title": "Agrokimyo", "desc": "pestitsid, gerbitsid, o'simlik himoya vositalari"}, {"title": "Texnik kimyo", "desc": "lak-bo'yoq, yuvish vositalari, sanoat gazlari"}, {"title": "Ekologiya", "desc": "gaz tozalash, oqava suv tozalash, neytralizatsiya"}]}, "why": {"label": "05 — Nima uchun aynan biz", "h2a": "Oltita sabab —", "h2b": "bitta javobgarlik", "items": [{"title": "Ongli ixtisoslashuv", "desc": "Butun e'tiborimiz kimyo obyektlarida: material tanlash, futerovka, nerjaveyka payvandlash va agressiv muhitdan himoya bo'yicha tayyorgarlik ko'rdik."}, {"title": "Bitta pudratchi — barcha ishlar", "desc": "Quvur bir firmada, futerovka boshqasida bo'lsa — muddat buziladi. Bizda hammasi bitta shartnoma va bitta javobgarlik ostida."}, {"title": "Material — muhitga qarab", "desc": "Konsentratsiya, harorat va rejimni so'raymiz, keyin tizimni taklif qilamiz. Kerak bo'lsa arzonroq, lekin ishlaydigan alternativani ko'rsatamiz."}, {"title": "Ishlayotgan korxonada", "desc": "Ishlab chiqarishni to'xtatmasdan, smenali va tungi rejimda ishlaymiz. To'xtatish remonti uchun brigada va grafikni oldindan rejalashtiramiz."}, {"title": "Hujjatlashtirilgan sifat", "desc": "Tozalash darajasi, qoplama qalinligi, chok nazorati, gidrosinov — hammasi akt va protokol bilan. Ijro hujjatlarini to'liq topshiramiz."}, {"title": "Xavfsizlik — birinchi o'rinda", "desc": "Gaz analizatori, iskra chiqmaydigan asbob, maxsus kiyim. Obyektda buyurtmachining rejimi so'zsiz bajariladi."}]}, "projects": {"label": "06 — Obyektlar", "h2a": "Bajarilgan ishlarimizdan", "h2b": "lavhalar", "note": "Kimyo obyektlari bo'yicha portfolio shakllantirilmoqda — sizni qiziqtirgan ish turi bo'yicha loyihalarimiz fotosi va hajmlarini so'rov bo'yicha yuboramiz.", "gallery": [{"alt": "Sovuq izolyatsiya — kollektor tugunlari", "caption": "Sovuq izolyatsiya — kollektor tugunlari"}, {"alt": "Issiqlik izolyatsiyasi — texnologik sig'imlar", "caption": "Issiqlik izolyatsiyasi — sig'imlar"}, {"alt": "Balandlikdagi ishlar — xavfsizlik nazorati", "caption": "Balandlikdagi ishlar — xavfsizlik nazorati"}, {"alt": "Magistral quvur izolyatsiyasi", "caption": "Magistral quvur izolyatsiyasi"}, {"alt": "Kolonna va apparatlar izolyatsiyasi", "caption": "Kolonna va apparatlar izolyatsiyasi"}, {"alt": "Gorizontal rezervuar izolyatsiyasi", "caption": "Gorizontal rezervuar izolyatsiyasi"}, {"alt": "Elektr isitish tizimlari", "caption": "Elektr isitish (obogrev) tizimlari"}, {"alt": "Sanoat lesa montaji", "caption": "Sanoat lesa montaji"}, {"alt": "Texnologik sig'imlar qoplamasi", "caption": "Texnologik sig'imlar qoplamasi"}, {"alt": "Minora inshootlarida lesa ishlari", "caption": "Minora inshootlarida lesa ishlari"}, {"alt": "Nasos guruhi va quvurlar izolyatsiyasi", "caption": "Nasos guruhi va quvurlar izolyatsiyasi"}, {"alt": "Quvur burilishi va armatura — metall qoplama", "caption": "Quvur burilishi va armatura — metall qoplama"}, {"alt": "Havo kanallari va armatura qutilari", "caption": "Havo kanallari va armatura qutilari"}, {"alt": "Nasoslar va kompensatorlar uchastkasi", "caption": "Nasoslar va kompensatorlar uchastkasi"}, {"alt": "Estakada metallokonstruksiyalari va quvurlar", "caption": "Estakada metallokonstruksiyalari va quvurlar"}, {"alt": "Qurilma umumiy ko'rinishi — issiqlik izolyatsiyasi", "caption": "Qurilma umumiy ko'rinishi — issiqlik izolyatsiyasi"}, {"alt": "Gorizontal apparat izolyatsiyasi va montaji", "caption": "Gorizontal apparat izolyatsiyasi va montaji"}, {"alt": "Yirik diametrli quvur burilishi", "caption": "Yirik diametrli quvur burilishi"}, {"alt": "Vertikal apparatlar va quvur tugunlari", "caption": "Vertikal apparatlar va quvur tugunlari"}, {"alt": "Issiqlik almashtirgichlar izolyatsiyasi", "caption": "Issiqlik almashtirgichlar izolyatsiyasi"}, {"alt": "Apparatlar guruhi — qoplama qatlami", "caption": "Apparatlar guruhi — qoplama qatlami"}, {"alt": "Kolonna izolyatsiyasi — to'liq balandlik", "caption": "Kolonna izolyatsiyasi — to'liq balandlik"}, {"alt": "Sex ichidagi quvur tizimlari izolyatsiyasi", "caption": "Sex ichidagi quvur tizimlari izolyatsiyasi"}, {"alt": "Qurilma va estakada — umumiy plan", "caption": "Qurilma va estakada — umumiy plan"}, {"alt": "Zapor armatura tugunlari izolyatsiyasi", "caption": "Zapor armatura tugunlari izolyatsiyasi"}, {"alt": "Kolonnalar qatori — metall qoplama", "caption": "Kolonnalar qatori — metall qoplama"}, {"alt": "Turbina uchun yechiladigan matras izolyatsiya", "caption": "Turbina uchun yechiladigan matras izolyatsiya"}, {"alt": "Armatura va flanslar uchun matras izolyatsiya", "caption": "Armatura va flanslar uchun matras izolyatsiya"}, {"alt": "Payvand chokini vizual nazorat qilish", "caption": "Payvand chokini vizual nazorat qilish"}, {"alt": "Rezervuar choki — sifat nazorati", "caption": "Rezervuar choki — sifat nazorati"}, {"alt": "Payvand choki — yaqindan ko'rinish", "caption": "Payvand choki — yaqindan ko'rinish"}, {"alt": "Apparat ichida payvandlash ishlari", "caption": "Apparat ichida payvandlash ishlari"}, {"alt": "Nerjaveyka troynik — argon payvandlash", "caption": "Nerjaveyka troynik — argon payvandlash"}, {"alt": "Quvur spuli sexda yig'ilmoqda", "caption": "Quvur spuli sexda yig'ilmoqda"}, {"alt": "Apparat tubi — halqa choki", "caption": "Apparat tubi — halqa choki"}, {"alt": "Flansli burilish tugunini tayyorlash", "caption": "Flansli burilish tugunini tayyorlash"}, {"alt": "Nerjaveykadan kollektor obvyazkasi", "caption": "Nerjaveykadan kollektor obvyazkasi"}, {"alt": "Sexda apparat va quvur obvyazkasi montaji", "caption": "Sexda apparat va quvur obvyazkasi montaji"}, {"alt": "Sex payvandchisi ish o'rnida", "caption": "Sex payvandchisi ish o'rnida"}, {"alt": "Balandlikda ishlash — ko'targich bilan izolyatsiya", "caption": "Balandlikda ishlash — ko'targich bilan izolyatsiya"}], "filters": {"all": "Hammasi", "ins": "Izolyatsiya va qoplama", "mat": "Matras izolyatsiya", "weld": "Payvandlash va nazorat", "shop": "Sexda tayyorlash", "lesa": "Lesa va balandlik"}}, "process": {"label": "07 — Ish jarayoni", "h2a": "Murojaatdan topshirishgacha —", "h2b": "to'rt qadam", "items": [{"title": "Murojaat va ko'rik", "desc": "1 ish kuni ichida bog'lanamiz. Mutaxassis obyektga chiqib, hajmlarni o'lchaydi va muhitlar bo'yicha ma'lumot to'playdi."}, {"title": "Texnik yechim va smeta", "desc": "Material va qoplama tizimini muhitga moslab tanlaymiz. Hajmlar vedomosti, spetsifikatsiya va grafik — odatda 2–5 ish kuni."}, {"title": "Shartnoma va boshlash", "desc": "Muddat, narx, kafolat va topshirish tartibi aniq yoziladi. Brigada va materiallar obyektga chiqadi."}, {"title": "Nazorat va topshirish", "desc": "Bosqichma-bosqich fotoreport, sinovlar, aktlar va ijro hujjatlari. Kafolat: 12–36 oy."}]}, "safety": {"label": "08 — Xavfsizlik va sifat", "h2a": "Bitta nazorat tizimi —", "h2b": "ikki natija: xavfsizlik va sifat", "col1": {"title": "Xavfsizlik", "items": ["Mehnat muhofazasi va gaz xavfsizligi bo'yicha o'qitilgan xodimlar", "Balandlik, olovli ish va gaz xavfli ishlar uchun naryad-dopusk", "Havo muhitini gaz analizatori bilan nazorat qilish", "Ex-zonalarda iskra chiqmaydigan asbob va uskunalar", "Kislotaga chidamli kostyum, respirator, straxovka", "Buyurtmachining LOTO va ruxsatnoma tizimiga to'liq rioya"]}, "col2": {"title": "Sifat", "items": ["Materiallar muhit bo'yicha tanlanadi, sertifikat bilan qabul qilinadi", "Nerjaveyka uchun alohida asbob va uchastka", "Operatsion nazorat: har bir bosqich yopilishidan oldin tekshiriladi", "Qoplama qalinligi (DFT) har bir qatlamda o'lchanadi", "Futerovka uchqun defektoskopi bilan tekshiriladi", "Yakuniy sinov protokollari va ijro hujjatlari topshiriladi"]}}, "faq": {"label": "09 — Savol-javob", "h2a": "Ko'p so'raladigan", "h2b": "savollar", "items": [{"q": "Kimyo sohasida tajribangiz bormi?", "a": "Ochiq javob beramiz: tajribamiz sanoat qurilish-montaj ishlarida to'plangan — metallokonstruksiya, payvandlash, quvur tizimlari, rezervuar montaji, izolyatsiya. Aynan shu ishlar kimyo zavodida ham bajariladi, faqat yuqoriroq talablar bilan. Birinchi kimyo loyihalarida kuchaytirilgan texnik nazorat bilan yoki tor yo'nalish bo'yicha subpudratchi sifatida ishlashga tayyormiz — natija uchun bu eng to'g'ri format."}, {"q": "Zavodni to'xtatmasdan ishlay olasizmi?", "a": "Ha. Ishlayotgan korxonalarda, ishlab chiqarishni to'xtatmasdan, smenali va tungi rejimda ishlash tajribamiz bor. To'xtatish remonti uchun brigada va grafikni oldindan rejalashtiramiz."}, {"q": "Qanday muhitlar uchun yechim taklif qila olasiz?", "a": "Oltingugurt, azot va fosfor kislotasi, ishqor, ammiak, o'g'it eritmalari, organik erituvchilar. Muhit, konsentratsiya va haroratni aytsangiz — mos material, futerovka va qoplama tizimini hisoblab taklif qilamiz."}, {"q": "Faqat bitta yo'nalishga buyurtma bersam bo'ladimi?", "a": "Albatta. Ko'p mijozlar bitta yo'nalishdan boshlaydi — masalan, faqat futerovka yoki faqat izolyatsiya — keyin qolgan ishlarni ham bizga topshiradi."}, {"q": "Portlash xavfli zonada ishlaysizmi?", "a": "Ha, faqat naryad-dopusk tizimi bo'yicha: gaz analizatori bilan nazorat, iskra chiqmaydigan asbob, olovli ishlar uchun alohida ruxsat va yong'in posti."}, {"q": "Material sizdanmi yoki buyurtmachidanmi?", "a": "Ikkala variant ham ishlaydi. Materialni o'zimiz yetkazib berganda odatda narx pastroq bo'ladi va javobgarlik bir joyda to'planadi."}, {"q": "Viloyatlarga chiqasizmi?", "a": "Ha, O'zbekistonning barcha hududlarida ishlaymiz. Jamoa vaxta usulida chiqadi, texnika obyektga yetkaziladi."}, {"q": "Kafolat va hujjatlar bo'yicha nima beriladi?", "a": "Ish turiga qarab 12–36 oy kafolat. Hujjatlar: aktlar, sinov protokollari, qoplama qalinligi o'lchovlari, ijro sxemalari, material sertifikatlari."}]}, "cta": {"label": "10 — Aloqa", "h2a": "Loyihangizni", "h2b": "muhokama qilaylik", "lead": "Chizmani yoki obyekt tavsifini yuboring — muhit va sharoitni hisobga olgan holda <b>2 ish kuni ichida</b> taklif tayyorlaymiz. Ko'rik bepul.", "phoneLabel": "Telefon", "telegramLabel": "Telegram", "telegramValue": "Yozish uchun bosing", "emailLabel": "E-mail", "addressLabel": "Manzil", "addressValue": "Samarqand viloyati, Paxtachi tumani, Burkut", "hoursLabel": "Ish vaqti", "hoursValue": "Du–Sha 9:00–18:00 · obyektlarda 24/7", "form": {"nameLabel": "Ismingiz", "namePh": "Ismingiz", "phoneLabel": "Telefon *", "phonePh": "+998 __ ___-__-__", "companyLabel": "Kompaniya", "companyPh": "Kompaniya nomi", "serviceLabel": "Xizmat", "servicePlaceholder": "Tanlang…", "serviceOptions": ["Quvur o'tkazgichlar montaji", "Uskunalar montaji", "Rezervuarlar montaji", "Metallokonstruksiyalar", "Argon payvandlash", "Elektr payvandlash", "Peskostruy", "Kimyoviy chidamli qoplamalar", "Sanoat izolyatsiyasi", "Lesa montaji", "Futerovka (plitka/g'isht)", "Boshqa"], "envLabel": "Muhit va sharoit", "envPh": "Masalan: 96% H₂SO₄, 60°C", "msgLabel": "Obyekt haqida qisqacha", "msgPh": "Obyekt, hajm, muddat…", "submit": "Arizani yuborish", "note": "Ma'lumotlaringiz uchinchi shaxslarga berilmaydi.", "ok": "Rahmat! Arizangiz qabul qilindi. Menejerimiz tez orada bog'lanadi."}}, "footer": {"tagline": "Sanoat qurilishi & montaj", "about": "Kimyo sanoati obyektlarini qurish va montaj qilish bo'yicha to'liq tsiklli pudratchi. O'zbekiston bo'ylab ishlaymiz.", "servicesTitle": "Xizmatlar", "servicesLinks": ["Quvur tizimlari", "Uskuna va rezervuar montaji", "Metallokonstruksiyalar", "Argon va elektr payvandlash", "Qoplamalar va futerovka", "Izolyatsiya", "Lesa montaji"], "companyTitle": "Kompaniya", "companyLinks": ["Biz haqimizda", "Obyektlar", "Savol-javob", "Aloqa"], "reqTitle": "Rekvizitlar", "reqDirectorLabel": "Direktor", "rights": "Barcha huquqlar himoyalangan."}}, ru: {"meta": {"title": "Pakhtachi Stone Group — строительство и монтаж химических заводов", "description": "Строим объекты химической промышленности полным циклом: монтаж оборудования, кислотопроводы, футеровка, химически стойкие покрытия и изоляция. По всему Узбекистану."}, "aria": {"brand": "Pakhtachi Stone Group — главная страница", "nav": "Основная навигация", "burgerOpen": "Открыть меню", "lightboxClose": "Закрыть", "lightboxPrev": "Предыдущее", "lightboxNext": "Следующее"}, "brand": {"tagline": "Промышленное строительство и монтаж"}, "nav": {"about": "О нас", "services": "Услуги", "stages": "Этапы", "projects": "Объекты", "faq": "Частые вопросы", "contact": "Контакты", "cta": "Получить смету"}, "hero": {"kicker": "Узбекистан · Самарканд · с 2016 года", "line1": "Химические заводы", "line2pre": "строительство и ", "line2em": "монтаж", "line3": "от проекта до запуска", "lead": "Реакторы и колонны, кислотостойкие трубопроводные системы, монтаж резервуаров и футеровка, аргонная сварка, химически стойкие покрытия и изоляция — все работы, необходимые химическому заводу, у одного подрядчика.", "cta1": "Рассчитать проект", "cta2": "Ознакомиться с услугами", "stat1": "год — в промышленном монтаже", "stat2": "сотрудников — в собственном штате", "stat3": "инженеров и технических специалистов", "stat4": "максимальная экономия энергии"}, "about": {"label": "01 — О нас", "h2a": "Для промышленных объектов", "h2b": "подрядчик полного цикла", "lead": "«Pakhtachi Stone Group» — подрядная организация, выполняющая строительно-монтажные работы на промышленных объектах. Монтаж металлоконструкций, сварка, трубопроводные системы, монтаж резервуаров и оборудования, антикоррозионная защита, изоляция и работы с лесами — всё это наша повседневная работа.", "p1": "Сегодня мы осознанно направляем свои усилия на <b>объекты химической промышленности</b>. Причина проста: работы, которые требует химический завод, — это именно те работы, которые мы выполняем, только в условиях повышенных требований и агрессивной среды. По этому направлению мы готовим нашу команду, формируем материальную и технологическую базу.", "p2": "В области технической изоляции компания предлагает весь спектр услуг для промышленных установок — от тепловой, холодовой, звуковой и противопожарной защиты до специальной изоляции для газовых турбин. Работаем с партнёрами из Европы и стран СНГ.", "principle": "Наш принцип: объект должен быть сдан в срок, по проекту и <em>безопасно</em>.", "photoAlt": "Изоляция технологических трубопроводов — объект Pakhtachi Stone Group", "points": ["Надёжный партнёр в промышленном строительстве", "Высококачественные услуги, соответствующие международным стандартам", "Решения, повышающие эффективность, энергосбережение и безопасность", "Один договор — одна ответственность"]}, "services": {"label": "02 — Услуги", "h2a": "Все работы, необходимые химическому заводу", "h2b": "— у одного подрядчика", "items": [{"name": "Монтаж трубопроводов", "tag": "Агрессивные среды", "body": "На химическом заводе трубопроводная система — самое слабое место: один участок с неверно подобранным материалом останавливает всю линию. Мы подбираем трубы в зависимости от среды, температуры и концентрации.", "li": ["Трубопроводы для кислот и щелочей (H₂SO₄, HNO₃, H₃PO₄, NaOH)", "Системы из нержавеющей стали — AISI 304, 316L, 321, duplex", "Полимерные трубопроводы: PP, PVDF, PE100, PVX", "Футерованные трубопроводы (резина, фторопласт, эмаль)", "Монтаж запорно-регулирующей арматуры", "Гидравлические и пневматические испытания, пассивация, маркировка"]}, {"name": "Монтаж оборудования", "tag": "Реактор · Колонна", "body": "Реактор, колонна, теплообменник — сердце химического завода. Точность установки измеряется в миллиметрах, схема подъёма разрабатывается и утверждается заранее.", "li": ["Установка реакторов, колонн, абсорберов и скрубберов", "Теплообменники, сушилки, грануляторы, фильтры", "Насосы, компрессоры и оборудование газоочистки", "Центровка лазерным прибором, анкеровка и подливка", "Обвязка, подключение КИПиА, испытание и пуск в эксплуатацию", "Опыт работы в окне остановочного ремонта"]}, {"name": "Монтаж резервуаров", "tag": "RVS · RGS", "body": "Ёмкости для хранения кислот, щелочей и реагентов — это объект, где сочетаются давление, агрессивная среда и экологический риск. Здесь одинаково важны и сварной шов, и внутреннее покрытие.", "li": ["Вертикальные и горизонтальные стальные резервуары (RVS, RGS)", "Ёмкости, миксеры и реакторы из нержавеющей стали", "Полипропиленовые и стеклопластиковые (FRP/GRP) ёмкости", "Внутренняя футеровка: гуммирование, фторопласт, кислотоупорный кирпич", "Испытание на герметичность, контроль покрытия искровым дефектоскопом", "Очистка, ремонт, замена днища и нижнего пояса стенки"]}, {"name": "Металлоконструкции", "tag": "Изготовление + монтаж", "body": "На химическом заводе металлический каркас постоянно работает в агрессивной атмосфере. Мы сдаём конструкцию не только прочной, но и защищённой на уровне C5/CX.", "li": ["Каркасы промышленных зданий и цехов", "Этажерки для аппаратов, трубопроводные эстакады", "Обслуживающие площадки, лестницы, ограждения", "Бункеры, силосы и конвейерные галереи", "Конструкции из нержавеющей стали и алюминия", "Монтаж с геодезическим контролем"]}, {"name": "Аргонодуговая сварка (TIG)", "tag": "Нержавейка · Сталь", "body": "На ответственных линиях корневой шов выполняем в аргоне, заполнение — электродом или полуавтоматом: шов получается гладким изнутри, поток не нарушается.", "li": ["Сварка AISI 304, 316L, 321, duplex", "Корневой шов с поддувом аргона внутрь", "Алюминий, титан, медь и специальные сплавы", "Травление и пассивация швов", "Импульсные линии (КИПиА) — полностью в аргоне", "Аттестованные сварщики"]}, {"name": "Электродуговая сварка", "tag": "MMA · MIG/MAG", "body": "Каждый ответственный шов нумеруется и закрепляется за сварщиком, проводится ВИК, при необходимости — неразрушающий контроль (РК/УЗК).", "li": ["Ручная дуговая сварка (MMA/РДС)", "Полуавтоматическая сварка (MIG/MAG)", "Монтажная сварка на высоте", "Многослойная сварка толстостенных аппаратов", "Восстановление участков, подвергшихся коррозии", "Огневые работы во взрывоопасных зонах (Ex) — по наряду-допуску"]}, {"name": "Пескоструйная очистка", "tag": "Sa 2½ · ISO 8501", "body": "80% успеха покраски и футеровки — это очистка поверхности. Агрессивная среда за несколько месяцев выявит любую слабую адгезию.", "li": ["Очистка до степени Sa 2 — Sa 2½ — Sa 3", "Подготовка внутренней и наружной поверхности резервуаров под футеровку", "Очистка бетонных поверхностей", "Безжелезистый абразив для нержавеющей стали", "Контроль шероховатости Rz, пыли и солевых остатков", "Температура металла — не менее чем на 3°C выше точки росы"]}, {"name": "Химически стойкие покрытия", "tag": "C5-I / CX", "body": "Атмосфера химического завода по ISO 12944 обычно относится к категории C5-I или CX — самые тяжёлые условия. Здесь обычная эмаль не работает.", "li": ["Системы: цинконаполненная грунтовка + эпоксид + полиуретан", "Винилэфирные, эпоксидно-фенольные, новолачные покрытия", "Внутреннее покрытие резервуаров", "Термостойкие покрытия (200–600°C)", "Химически стойкие промышленные полы", "Контроль DFT и искровая дефектоскопия"]}, {"name": "Промышленная изоляция", "tag": "Тепло · Холод · CUI", "body": "Экономия энергии, соблюдение технологического режима, защита персонала — и защита металла от коррозии под изоляцией (CUI). Отдельный опыт — изоляция турбин.", "li": ["Изоляция трубопроводов, реакторов и резервуаров", "Матрасная изоляция для газовых и паровых турбин", "Холодная изоляция: линии аммиака, фреона — с пароизоляционным барьером", "Материалы: базальтовая вата, ППУ, пеностекло, керамическая вата", "Защитная обшивка — по размеру, на собственном станке", "Системы электрообогрева и защиты от замерзания"]}, {"name": "Монтаж промышленных лесов", "tag": "Монтаж + аренда", "body": "Предлагаем полный спектр промышленных, специальных и фасадных лесов — для отдельных объектов, крупных проектов и долгосрочных договоров.", "li": ["Рамные, хомутовые, клиновые и модульные системы", "Леса вокруг реакторов, колонн и печей", "Подвесные леса и консольные площадки", "Грузоподъёмники — до 2 000 кг, до 120 м", "Аренда лесов — с монтажом и демонтажом", "Каждые леса принимаются в эксплуатацию с биркой"]}, {"name": "Кислотостойкая футеровка", "tag": "Плитка · Кирпич", "body": "Там, где высокая концентрация, температура и механическая нагрузка, футеровка плиткой и кирпичом — самое надёжное решение: она служит десятилетиями. Облицовываем как стены, так и днище в самых тяжёлых условиях.", "li": ["Внутренняя футеровка кислотных резервуаров", "Ванны нейтрализации, приёмники и зумпфы", "Диабазовая плитка, KKG, шамотный и угольный кирпич", "Силикатная, фурановая, эпоксидная и винилэфирная замазки", "Герметичный подслой: гуммирование или эпоксидный барьер", "Искровой/вакуумный контроль, испытание водой"]}]}, "stages": {"label": "03 — Этапы строительства", "h2a": "Объект принимаем как", "h2b": "технологическую цепочку", "items": [{"title": "Проект и подготовка", "desc": "Осмотр объекта, изучение перечня сред, подбор материалов под условия эксплуатации, смета и график."}, {"title": "Фундамент и подземная часть", "desc": "Фундамент и анкеры, кислотостойкие поддоны, дренаж и система отведения стоков."}, {"title": "Металлический каркас", "desc": "Монтаж колонн и ферм, трубопроводные эстакады, этажерки и площадки."}, {"title": "Монтаж оборудования", "desc": "Реакторы, колонны, теплообменники, насосы и компрессоры. Точная центровка."}, {"title": "Трубопроводные системы", "desc": "Для каждой среды — своя линия. Арматура, компенсаторы, испытания и маркировка."}, {"title": "Защитные слои", "desc": "Футеровка, антикоррозионная система, тепловая и холодная изоляция, защита от коррозии под изоляцией (CUI)."}, {"title": "Испытания и сдача", "desc": "Гидравлические и пневматические испытания, промывка, испытание на холостом ходу, исполнительная документация."}]}, "industries": {"label": "04 — Направления", "h2a": "В каких направлениях", "h2b": "химической промышленности мы работаем", "items": [{"title": "Минеральные удобрения", "desc": "аммиак, карбамид, селитра, аммофос, суперфосфат"}, {"title": "Кислоты", "desc": "установки серной, азотной, фосфорной кислоты"}, {"title": "Хлор-щелочь и сода", "desc": "производственные установки"}, {"title": "Полимеры", "desc": "полиэтилен, полипропилен, PVX, линии гранулирования"}, {"title": "Нефтехимия", "desc": "переработка газа, метанол, растворители"}, {"title": "Агрохимия", "desc": "пестициды, гербициды, средства защиты растений"}, {"title": "Техническая химия", "desc": "лакокрасочные материалы, моющие средства, промышленные газы"}, {"title": "Экология", "desc": "очистка газов, очистка сточных вод, нейтрализация"}]}, "why": {"label": "05 — Почему именно мы", "h2a": "Шесть причин —", "h2b": "одна ответственность", "items": [{"title": "Осознанная специализация", "desc": "Всё наше внимание — на химических объектах: мы подготовлены в подборе материалов, футеровке, сварке нержавеющей стали и защите от агрессивных сред."}, {"title": "Один подрядчик — все работы", "desc": "Если трубопроводы у одной компании, а футеровка у другой — сроки срываются. У нас всё выполняется по одному договору и под одной ответственностью."}, {"title": "Материал — в зависимости от среды", "desc": "Уточняем концентрацию, температуру и режим, затем предлагаем систему. При необходимости показываем более дешёвую, но рабочую альтернативу."}, {"title": "На действующем предприятии", "desc": "Работаем в сменном и ночном режиме, не останавливая производство. Для остановочного ремонта заранее планируем бригаду и график."}, {"title": "Документированное качество", "desc": "Степень очистки, толщина покрытия, контроль швов, гидроиспытания — всё оформляется актами и протоколами. Исполнительную документацию передаём в полном объёме."}, {"title": "Безопасность — на первом месте", "desc": "Газоанализатор, искробезопасный инструмент, спецодежда. На объекте безоговорочно соблюдается регламент заказчика."}]}, "projects": {"label": "06 — Объекты", "h2a": "Кадры", "h2b": "выполненных нами работ", "note": "Портфолио по химическим объектам формируется — фото и объёмы наших проектов по интересующему вас виду работ предоставим по запросу.", "gallery": [{"alt": "Холодная изоляция — узлы коллекторов", "caption": "Холодная изоляция — узлы коллекторов"}, {"alt": "Тепловая изоляция — технологические ёмкости", "caption": "Тепловая изоляция — ёмкости"}, {"alt": "Высотные работы — контроль безопасности", "caption": "Высотные работы — контроль безопасности"}, {"alt": "Изоляция магистральных трубопроводов", "caption": "Изоляция магистральных трубопроводов"}, {"alt": "Изоляция колонн и аппаратов", "caption": "Изоляция колонн и аппаратов"}, {"alt": "Изоляция горизонтальных резервуаров", "caption": "Изоляция горизонтальных резервуаров"}, {"alt": "Системы электрообогрева", "caption": "Системы электрического обогрева"}, {"alt": "Монтаж промышленных лесов", "caption": "Монтаж промышленных лесов"}, {"alt": "Покрытие технологических ёмкостей", "caption": "Покрытие технологических ёмкостей"}, {"alt": "Устройство лесов на башенных сооружениях", "caption": "Устройство лесов на башенных сооружениях"}, {"alt": "Изоляция насосной группы и трубопроводов", "caption": "Изоляция насосной группы и трубопроводов"}, {"alt": "Отвод и арматура — металлическая обшивка", "caption": "Отвод и арматура — металлическая обшивка"}, {"alt": "Воздуховоды и короба арматуры", "caption": "Воздуховоды и короба арматуры"}, {"alt": "Участок насосов и компенсаторов", "caption": "Участок насосов и компенсаторов"}, {"alt": "Металлоконструкции эстакады и трубопроводы", "caption": "Металлоконструкции эстакады и трубопроводы"}, {"alt": "Общий вид установки — тепловая изоляция", "caption": "Общий вид установки — тепловая изоляция"}, {"alt": "Изоляция и монтаж горизонтального аппарата", "caption": "Изоляция и монтаж горизонтального аппарата"}, {"alt": "Отвод трубопровода большого диаметра", "caption": "Отвод трубопровода большого диаметра"}, {"alt": "Вертикальные аппараты и узлы трубопроводов", "caption": "Вертикальные аппараты и узлы трубопроводов"}, {"alt": "Изоляция теплообменников", "caption": "Изоляция теплообменников"}, {"alt": "Группа аппаратов — защитная обшивка", "caption": "Группа аппаратов — защитная обшивка"}, {"alt": "Изоляция колонны на всю высоту", "caption": "Изоляция колонны на всю высоту"}, {"alt": "Изоляция трубопроводов внутри цеха", "caption": "Изоляция трубопроводов внутри цеха"}, {"alt": "Установка и эстакада — общий план", "caption": "Установка и эстакада — общий план"}, {"alt": "Изоляция узлов запорной арматуры", "caption": "Изоляция узлов запорной арматуры"}, {"alt": "Ряд колонн — металлическая обшивка", "caption": "Ряд колонн — металлическая обшивка"}, {"alt": "Съёмная матрасная изоляция турбины", "caption": "Съёмная матрасная изоляция турбины"}, {"alt": "Матрасная изоляция арматуры и фланцев", "caption": "Матрасная изоляция арматуры и фланцев"}, {"alt": "Визуальный контроль сварного шва", "caption": "Визуальный контроль сварного шва"}, {"alt": "Шов резервуара — контроль качества", "caption": "Шов резервуара — контроль качества"}, {"alt": "Сварной шов — крупный план", "caption": "Сварной шов — крупный план"}, {"alt": "Сварочные работы внутри аппарата", "caption": "Сварочные работы внутри аппарата"}, {"alt": "Тройник из нержавейки — аргонная сварка", "caption": "Тройник из нержавейки — аргонная сварка"}, {"alt": "Сборка трубного узла в цехе", "caption": "Сборка трубного узла в цехе"}, {"alt": "Днище аппарата — кольцевой шов", "caption": "Днище аппарата — кольцевой шов"}, {"alt": "Изготовление отвода с фланцем", "caption": "Изготовление отвода с фланцем"}, {"alt": "Обвязка коллектора из нержавеющей стали", "caption": "Обвязка коллектора из нержавеющей стали"}, {"alt": "Монтаж аппарата и обвязки в цехе", "caption": "Монтаж аппарата и обвязки в цехе"}, {"alt": "Сварщик цеха на рабочем месте", "caption": "Сварщик цеха на рабочем месте"}, {"alt": "Работа на высоте — изоляция с подъёмника", "caption": "Работа на высоте — изоляция с подъёмника"}], "filters": {"all": "Все", "ins": "Изоляция и обшивка", "mat": "Матрасная изоляция", "weld": "Сварка и контроль", "shop": "Изготовление в цехе", "lesa": "Леса и высотные работы"}}, "process": {"label": "07 — Рабочий процесс", "h2a": "От обращения до сдачи объекта —", "h2b": "четыре шага", "items": [{"title": "Обращение и осмотр", "desc": "Свяжемся с вами в течение 1 рабочего дня. Специалист выезжает на объект, замеряет объёмы и собирает данные по средам эксплуатации."}, {"title": "Техническое решение и смета", "desc": "Подбираем материал и систему покрытия с учётом среды эксплуатации. Ведомость объёмов, спецификация и график — обычно 2–5 рабочих дней."}, {"title": "Договор и начало работ", "desc": "Чётко прописываем сроки, стоимость, гарантию и порядок сдачи. Бригада и материалы выезжают на объект."}, {"title": "Контроль и сдача", "desc": "Поэтапный фотоотчёт, испытания, акты и исполнительная документация. Гарантия: 12–36 месяцев."}]}, "safety": {"label": "08 — Безопасность и качество", "h2a": "Одна система контроля —", "h2b": "два результата: безопасность и качество", "col1": {"title": "Безопасность", "items": ["Персонал, обученный охране труда и газовой безопасности", "Наряд-допуск на высотные, огневые и газоопасные работы", "Контроль воздушной среды газоанализатором", "Искробезопасный инструмент и оборудование во взрывоопасных зонах (Ex)", "Кислотостойкий костюм, респиратор, страховочное снаряжение", "Полное соблюдение системы LOTO и разрешений заказчика"]}, "col2": {"title": "Качество", "items": ["Материалы подбираются по среде, принимаются с сертификатом", "Отдельные инструменты и участок для нержавеющей стали", "Операционный контроль: проверка перед закрытием каждого этапа", "Толщина покрытия (DFT) измеряется на каждом слое", "Футеровка проверяется искровым дефектоскопом", "Передаются итоговые протоколы испытаний и исполнительная документация"]}}, "faq": {"label": "09 — Вопросы и ответы", "h2a": "Часто задаваемые", "h2b": "вопросы", "items": [{"q": "Есть ли у вас опыт работы в химической отрасли?", "a": "Отвечаем честно: наш опыт накоплен в промышленном строительно-монтажном деле — металлоконструкции, сварка, трубопроводные системы, монтаж резервуаров, изоляция. Именно эти работы выполняются и на химическом заводе, только с более высокими требованиями. На первых химических проектах готовы работать с усиленным техническим контролем или в качестве субподрядчика по узкому направлению — для результата это наиболее правильный формат."}, {"q": "Можете ли вы работать без остановки завода?", "a": "Да. У нас есть опыт работы на действующих предприятиях, без остановки производства, посменно и в ночном режиме. Для остановочного ремонта бригаду и график планируем заранее."}, {"q": "Для каких сред вы можете предложить решение?", "a": "Серная, азотная и фосфорная кислота, щёлочь, аммиак, растворы удобрений, органические растворители. Если вы укажете среду, концентрацию и температуру — мы рассчитаем и предложим подходящий материал, футеровку и систему покрытия."}, {"q": "Можно ли заказать только одно направление работ?", "a": "Конечно. Многие клиенты начинают с одного направления — например, только футеровка или только изоляция — а затем передают нам и остальные работы."}, {"q": "Работаете ли вы во взрывоопасной зоне?", "a": "Да, но только по системе наряда-допуска: контроль газоанализатором, искробезопасный инструмент, отдельное разрешение на огневые работы и пожарный пост."}, {"q": "Материал от вас или от заказчика?", "a": "Работают оба варианта. Когда материал поставляем мы сами, цена обычно ниже, а ответственность сосредоточена в одних руках."}, {"q": "Выезжаете ли вы в регионы?", "a": "Да, мы работаем во всех регионах Узбекистана. Бригада выезжает вахтовым методом, техника доставляется на объект."}, {"q": "Что предоставляется по гарантии и документации?", "a": "Гарантия от 12 до 36 месяцев в зависимости от вида работ. Документы: акты, протоколы испытаний, замеры толщины покрытия, исполнительные схемы, сертификаты на материалы."}]}, "cta": {"label": "10 — Контакты", "h2a": "Ваш проект", "h2b": "давайте обсудим", "lead": "Пришлите чертёж или описание объекта — с учётом среды и условий подготовим предложение <b>в течение 2 рабочих дней</b>. Осмотр — бесплатно.", "phoneLabel": "Телефон", "telegramLabel": "Telegram", "telegramValue": "Нажмите, чтобы написать", "emailLabel": "E-mail", "addressLabel": "Адрес", "addressValue": "Самаркандская область, Пахтачийский район, Буркут", "hoursLabel": "Часы работы", "hoursValue": "Пн–Сб 9:00–18:00 · на объектах 24/7", "form": {"nameLabel": "Ваше имя", "namePh": "Ваше имя", "phoneLabel": "Телефон *", "phonePh": "+998 __ ___-__-__", "companyLabel": "Компания", "companyPh": "Название компании", "serviceLabel": "Услуга", "servicePlaceholder": "Выберите…", "serviceOptions": ["Монтаж трубопроводов", "Монтаж оборудования", "Монтаж резервуаров", "Металлоконструкции", "Аргонная сварка", "Электросварка", "Пескоструйная обработка", "Химически стойкие покрытия", "Промышленная изоляция", "Монтаж лесов", "Футеровка (плитка/кирпич)", "Другое"], "envLabel": "Среда и условия", "envPh": "Например: 96% H₂SO₄, 60°C", "msgLabel": "Кратко об объекте", "msgPh": "Объект, объём, сроки…", "submit": "Отправить заявку", "note": "Ваши данные не передаются третьим лицам.", "ok": "Спасибо! Ваша заявка принята. Наш менеджер скоро свяжется с вами."}}, "footer": {"tagline": "Промышленное строительство и монтаж", "about": "Подрядчик полного цикла по строительству и монтажу объектов химической промышленности. Работаем по всему Узбекистану.", "servicesTitle": "Услуги", "servicesLinks": ["Трубопроводные системы", "Монтаж оборудования и резервуаров", "Металлоконструкции", "Аргонная и электросварка", "Покрытия и футеровка", "Изоляция", "Монтаж лесов"], "companyTitle": "Компания", "companyLinks": ["О нас", "Объекты", "Вопрос-ответ", "Контакты"], "reqTitle": "Реквизиты", "reqDirectorLabel": "Директор", "rights": "Все права защищены."}}, zh: {"meta": {"title": "Pakhtachi Stone Group — 化工厂建设与安装", "description": "我们以全流程模式承建化工行业设施：设备安装、耐酸管道、衬里、耐化学涂层与保温。业务覆盖乌兹别克斯坦全境。"}, "aria": {"brand": "Pakhtachi Stone Group — 首页", "nav": "主导航", "burgerOpen": "打开菜单", "lightboxClose": "关闭", "lightboxPrev": "上一张", "lightboxNext": "下一张"}, "brand": {"tagline": "工业建设与安装"}, "nav": {"about": "关于我们", "services": "服务", "stages": "阶段", "projects": "项目", "faq": "常见问题", "contact": "联系我们", "cta": "获取报价"}, "hero": {"kicker": "乌兹别克斯坦 · 撒马尔罕 · 自2016年起", "line1": "化工厂", "line2pre": "建设与", "line2em": "安装", "line3": "从设计到投产", "lead": "反应釜与塔器、耐酸管道系统、储罐安装与衬里、氩弧焊、耐化学涂层与保温——化工厂所需的全部工作，一家总承包商即可完成。", "cta1": "计算项目报价", "cta2": "了解服务详情", "stat1": "年成立，深耕工业安装", "stat2": "名员工——自有团队", "stat3": "名工程师和技术专家", "stat4": "最大节能"}, "about": {"label": "01 — 关于我们", "h2a": "面向工业设施的", "h2b": "全周期总承包商", "lead": "Pakhtachi Stone Group 是一家在工业设施上从事建筑安装工程的总承包企业。金属结构安装、焊接、管道系统、储罐及设备安装、防腐保护、保温隔热及脚手架作业——这些都是我们的日常工作。", "p1": "如今，我们有意识地将力量集中投向<b>化工行业设施</b>。原因很简单：化工厂所需要的工作，正是我们所从事的工作，只是在更高要求和强腐蚀性环境条件下进行。围绕这一方向，我们正在培养团队，构建材料与技术基础。", "p2": "在技术保温领域，公司为工业装置提供从保温、保冷、隔音、防火保护到燃气轮机专用保温在内的全部服务。我们与欧洲和独联体国家的合作伙伴开展合作。", "principle": "我们的原则是：项目必须按时、按设计方案并<em>安全</em>交付。", "photoAlt": "工艺管道保温——Pakhtachi Stone Group 项目", "points": ["工业建设领域值得信赖的合作伙伴", "符合国际标准的高质量服务", "提升效率、节能与安全的解决方案", "一份合同——一份责任"]}, "services": {"label": "02 — 服务", "h2a": "化工厂所需的", "h2b": "全部工作——一家承包商即可完成", "items": [{"name": "管道安装", "tag": "腐蚀性介质", "body": "在化工厂中,管道系统是最薄弱的环节:材料选型错误的一段管道就会导致整条生产线停车。我们根据介质、温度和浓度选择管材。", "li": ["酸碱管道(H₂SO₄、HNO₃、H₃PO₄、NaOH)", "不锈钢系统 — AISI 304、316L、321、duplex", "聚合物管道:PP、PVDF、PE100、PVX", "衬里管道(橡胶、氟塑料、搪瓷)", "截止调节阀门安装", "水压和气压试验、钝化处理、标识"]}, {"name": "设备安装", "tag": "反应器 · 塔器", "body": "反应器、塔器、换热器 — 是化工厂的心脏。安装精度以毫米计算,吊装方案须事先设计并审批。", "li": ["反应器、塔器、吸收塔和洗涤塔的安装", "换热器、干燥器、造粒机、过滤器", "泵、压缩机及气体净化设备", "激光找正对中、地脚锚固及二次灌浆", "管道连接、仪表自动化系统接入、调试与投产", "具备停车检修窗口期作业经验"]}, {"name": "储罐安装", "tag": "RVS · RGS", "body": "存储酸、碱及各类试剂的容器 — 是集压力、腐蚀性介质与环境风险于一体的设施。焊缝和内衬防腐层同等重要。", "li": ["立式和卧式钢制储罐(RVS、RGS)", "不锈钢容器、搅拌釜和反应釜", "聚丙烯及玻璃钢(FRP/GRP)容器", "内衬防腐:橡胶衬里、氟塑料衬里、耐酸砖", "气密性试验、电火花检漏涂层检测", "清罐、维修、更换罐底及罐壁底圈板"]}, {"name": "金属结构", "tag": "生产+安装", "body": "在化工厂中,金属结构始终处于腐蚀性环境中工作。我们交付的结构不仅坚固,而且达到C5/CX级别的防腐保护。", "li": ["工业厂房及车间钢结构", "设备支撑框架、管道管廊", "操作平台、楼梯、护栏", "料仓、筒仓及输送机走廊", "不锈钢及铝合金结构", "带大地测量控制的安装"]}, {"name": "氩弧焊(TIG)", "tag": "不锈钢 · 钢材", "body": "在关键管线上,根部焊道采用氩弧焊,填充层用焊条或半自动焊完成——焊缝内壁光滑平整,不影响介质流动。", "li": ["焊接 AISI 304、316L、321、双相钢(duplex)", "内壁充氩保护的根部焊道", "铝、钛、铜及特种合金", "焊缝酸洗与钝化处理", "仪表自动化脉冲管线——全程氩气保护", "持证认证焊工"]}, {"name": "电弧焊", "tag": "MMA · MIG/MAG", "body": "每条关键焊缝都编号并落实到责任焊工,进行目视检测,必要时进行无损检测(射线检测/超声检测)。", "li": ["手工电弧焊(MMA/RDS)", "半自动焊(MIG/MAG)", "高空安装焊接", "厚壁设备的多层焊接", "腐蚀部位的修复", "防爆区(Ex)动火作业——凭工作许可证执行"]}, {"name": "喷砂清理", "tag": "Sa 2½ · ISO 8501", "body": "涂层和衬里成功的80%取决于表面清理。腐蚀性环境会在几个月内暴露任何附着力薄弱的地方。", "li": ["清理至 Sa 2 — Sa 2½ — Sa 3 等级", "储罐内外表面衬里前处理", "混凝土表面清理", "用于不锈钢的无铁磨料", "Rz 粗糙度、粉尘及盐分残留检测", "金属温度——高于露点至少3°C"]}, {"name": "耐化学腐蚀涂层", "tag": "C5-I / CX", "body": "根据 ISO 12944,化工厂的大气环境通常属于 C5-I 或 CX 类别——最严苛的腐蚀环境。普通瓷漆在这种条件下无法胜任。", "li": ["富锌底漆 + 环氧 + 聚氨酯体系", "乙烯基酯、环氧酚醛、酚醛清漆(novolac)涂层", "储罐内壁涂层", "耐高温涂层(200–600°C)", "耐化学腐蚀工业地坪", "DFT 检测与电火花检漏"]}, {"name": "工业保温", "tag": "保温 · 保冷 · CUI", "body": "节约能源、维持工艺制度、保护作业人员——并防止金属发生保温层下腐蚀(CUI)。我们在涡轮机保温方面拥有专门经验。", "li": ["管道、反应釜和储罐保温", "燃气轮机和汽轮机用保温毯", "保冷:氨、氟利昂管线——带隔汽层", "材料:玄武岩棉、聚氨酯泡沫、泡沫玻璃、陶瓷纤维棉", "包覆层——按尺寸,在自有设备上加工", "电伴热及防冻系统"]}, {"name": "工业脚手架搭设", "tag": "搭设+租赁", "body": "我们提供全系列工业、特种和外墙脚手架——适用于单个项目、大型工程和长期合同。", "li": ["框架式、扣件式、楔销式和模块化系统", "反应釜、塔器和炉体周围的脚手架", "悬挂式脚手架和悬臂式作业平台", "载货升降机——最大载重2000公斤,最高120米", "脚手架租赁——含搭设与拆除", "每个脚手架均带验收标签交付使用"]}, {"name": "耐酸衬里", "tag": "瓷板 · 砖", "body": "在高浓度、高温和机械负荷环境下,瓷板-耐酸砖衬里是最可靠的解决方案——可使用数十年之久。无论是墙面,还是最恶劣工况下的底部,我们都能施工。", "li": ["酸罐内部衬里", "中和槽、接收罐和集水坑", "辉绿岩板、KKG、粘土耐火砖和碳砖", "硅酸盐、呋喃、环氧、乙烯基酯胶泥", "密封底层:橡胶衬里或环氧树脂屏障层", "火花/真空检测、蓄水试验"]}]}, "stages": {"label": "03 — 施工阶段", "h2a": "我们将项目视为", "h2b": "工艺链条", "items": [{"title": "设计与准备", "desc": "现场勘查、研究介质清单、根据工况选配材料、编制预算和进度计划。"}, {"title": "基础与地下部分", "desc": "基础及锚栓、耐酸托盘、排水与污水排放系统。"}, {"title": "金属框架", "desc": "立柱与桁架安装、管道栈桥、多层管架与平台。"}, {"title": "设备安装", "desc": "反应器、塔器、换热器、泵与压缩机。精确找正。"}, {"title": "管道系统", "desc": "每种介质配备独立管线。阀门管件、补偿器、试压与标识。"}, {"title": "防护层", "desc": "衬里、防腐蚀系统、保温与保冷、CUI（保温层下腐蚀）防护。"}, {"title": "试验与交付", "desc": "水压和气压试验、冲洗、空载试运行、竣工技术文件。"}]}, "industries": {"label": "04 — 行业领域", "h2a": "我们在化工行业的", "h2b": "哪些领域开展工作", "items": [{"title": "矿物肥料", "desc": "氨、尿素、硝酸盐、磷酸铵、过磷酸钙"}, {"title": "酸类", "desc": "硫酸、硝酸、磷酸装置"}, {"title": "氯碱与纯碱", "desc": "生产装置"}, {"title": "聚合物", "desc": "聚乙烯、聚丙烯、PVX、造粒生产线"}, {"title": "石油化工", "desc": "气体加工、甲醇、溶剂"}, {"title": "农业化工", "desc": "农药、除草剂、植物保护制剂"}, {"title": "工业化学品", "desc": "涂料油漆、洗涤用品、工业气体"}, {"title": "环保", "desc": "废气净化、废水处理、中和处理"}]}, "why": {"label": "05 — 为什么选择我们", "h2a": "六个理由 —", "h2b": "一份责任", "items": [{"title": "专注化工领域", "desc": "我们的全部精力都投入化工设施：在材料选型、衬里施工、不锈钢焊接和防腐蚀防护方面积累了专业能力。"}, {"title": "一家承包商 — 全部工程", "desc": "如果管道由一家公司负责、衬里由另一家公司负责，工期就会延误。我们的所有工作都在同一份合同和同一责任范围内完成。"}, {"title": "根据介质选材", "desc": "我们先了解浓度、温度和工况，再提出方案。如有需要，也会提供更经济但同样有效的替代方案。"}, {"title": "在生产运行中的企业作业", "desc": "在不停产的前提下，采取倒班和夜间作业模式。针对停车检修，我们提前规划班组和进度计划。"}, {"title": "质量全程留痕", "desc": "除锈等级、涂层厚度、焊缝检测、水压试验——均出具验收记录和检测报告。竣工技术文件全套移交。"}, {"title": "安全 — 第一位", "desc": "气体检测仪、防爆工具、专用防护服。在现场无条件遵守业主的安全管理规定。"}]}, "projects": {"label": "06 — 工程案例", "h2a": "已完成工程的", "h2b": "实景影像", "note": "化工项目作品集正在完善中——我们将按您关注的工程类型,应要求发送相关项目照片及工程量信息。", "gallery": [{"alt": "冷保温 — 集管节点", "caption": "冷保温 — 集管节点"}, {"alt": "保温隔热 — 工艺容器", "caption": "保温隔热 — 容器"}, {"alt": "高空作业 — 安全监控", "caption": "高空作业 — 安全监控"}, {"alt": "主干管道保温", "caption": "主干管道保温"}, {"alt": "塔器与设备保温", "caption": "塔器与设备保温"}, {"alt": "卧式储罐保温", "caption": "卧式储罐保温"}, {"alt": "电伴热系统", "caption": "电伴热(电加热)系统"}, {"alt": "工业脚手架搭设", "caption": "工业脚手架搭设"}, {"alt": "工艺容器涂层", "caption": "工艺容器涂层"}, {"alt": "塔式构筑物脚手架作业", "caption": "塔式构筑物脚手架作业"}, {"alt": "泵组与管道保温", "caption": "泵组与管道保温"}, {"alt": "弯头与阀门 — 金属外护", "caption": "弯头与阀门 — 金属外护"}, {"alt": "风管与阀门保温箱", "caption": "风管与阀门保温箱"}, {"alt": "泵与补偿器区域", "caption": "泵与补偿器区域"}, {"alt": "管廊钢结构与管道", "caption": "管廊钢结构与管道"}, {"alt": "装置全景 — 保温隔热", "caption": "装置全景 — 保温隔热"}, {"alt": "卧式设备保温与安装", "caption": "卧式设备保温与安装"}, {"alt": "大口径管道弯头", "caption": "大口径管道弯头"}, {"alt": "立式设备与管道节点", "caption": "立式设备与管道节点"}, {"alt": "换热器保温", "caption": "换热器保温"}, {"alt": "设备群 — 保护外护层", "caption": "设备群 — 保护外护层"}, {"alt": "塔器全高保温", "caption": "塔器全高保温"}, {"alt": "车间内管道保温", "caption": "车间内管道保温"}, {"alt": "装置与管廊全景", "caption": "装置与管廊全景"}, {"alt": "阀门节点保温", "caption": "阀门节点保温"}, {"alt": "塔器列 — 金属外护", "caption": "塔器列 — 金属外护"}, {"alt": "汽轮机可拆卸保温被", "caption": "汽轮机可拆卸保温被"}, {"alt": "阀门与法兰保温被", "caption": "阀门与法兰保温被"}, {"alt": "焊缝目视检验", "caption": "焊缝目视检验"}, {"alt": "储罐焊缝 — 质量检验", "caption": "储罐焊缝 — 质量检验"}, {"alt": "焊缝特写", "caption": "焊缝特写"}, {"alt": "设备内部焊接作业", "caption": "设备内部焊接作业"}, {"alt": "不锈钢三通 — 氩弧焊", "caption": "不锈钢三通 — 氩弧焊"}, {"alt": "车间管段组对", "caption": "车间管段组对"}, {"alt": "设备封头 — 环焊缝", "caption": "设备封头 — 环焊缝"}, {"alt": "带法兰弯头制作", "caption": "带法兰弯头制作"}, {"alt": "不锈钢集管配管", "caption": "不锈钢集管配管"}, {"alt": "车间设备与配管安装", "caption": "车间设备与配管安装"}, {"alt": "车间焊工在工位", "caption": "车间焊工在工位"}, {"alt": "高空作业 — 升降平台保温", "caption": "高空作业 — 升降平台保温"}], "filters": {"all": "全部", "ins": "保温与外护", "mat": "可拆卸保温被", "weld": "焊接与检验", "shop": "车间制作", "lesa": "脚手架与高空作业"}}, "process": {"label": "07 — 工作流程", "h2a": "从洽谈到交付 —", "h2b": "四个步骤", "items": [{"title": "咨询与现场勘察", "desc": "我们将在1个工作日内与您联系。技术专家将赴现场测量工程量,并收集相关介质信息。"}, {"title": "技术方案与预算", "desc": "根据介质条件选择材料及涂层体系。工程量清单、技术规格书及进度表——通常需要2-5个工作日。"}, {"title": "签订合同并开工", "desc": "明确写明工期、价格、质保及交付流程。施工队和材料随即进场。"}, {"title": "监控与交付", "desc": "分阶段拍摄进度照片、进行测试、签署验收单及编制竣工文件。质保期:12-36个月。"}]}, "safety": {"label": "08 — 安全与质量", "h2a": "一套管控体系——", "h2b": "两个结果：安全与质量", "col1": {"title": "安全", "items": ["接受过劳动保护和燃气安全培训的员工", "高空作业、动火作业和有毒有害气体作业的工作许可证", "使用气体分析仪监测空气环境", "在防爆区域（Ex）使用防爆（不产生火花）工具和设备", "耐酸服、呼吸器、安全绳", "全面遵守业主的LOTO（能源隔离上锁挂牌）及许可制度"]}, "col2": {"title": "质量", "items": ["材料根据介质环境选型，凭合格证书验收", "不锈钢专用工具和作业区域", "工序检验：每个阶段封闭前进行检查", "每层涂层厚度（DFT）均进行测量", "衬里采用电火花检测仪进行检测", "提交最终测试报告及竣工文件"]}}, "faq": {"label": "09 — 常见问题解答", "h2a": "常见", "h2b": "问题", "items": [{"q": "您在化工领域有经验吗？", "a": "坦诚回答：我们的经验积累于工业建筑安装工程——金属结构、焊接、管道系统、储罐安装、保温。这些工作在化工厂同样需要完成，只是要求更高。在最初的化工项目中，我们愿意在加强技术监督下工作，或作为窄专业方向的分包商参与——从结果角度看，这是最合适的合作方式。"}, {"q": "能否在不停产的情况下施工？", "a": "可以。我们有在运行中的企业内、在不停产的情况下、按班次及夜间模式施工的经验。对于停产检修，我们会提前规划好班组和进度计划。"}, {"q": "您能针对哪些介质提供解决方案？", "a": "硫酸、硝酸和磷酸、碱、氨、化肥溶液、有机溶剂。如果您告知介质种类、浓度和温度，我们将据此计算并提供合适的材料、衬里及涂层系统。"}, {"q": "可以只委托一个业务方向吗？", "a": "当然可以。许多客户从一个方向开始——例如只做衬里或只做保温——之后再将其余工作也委托给我们。"}, {"q": "您们能在防爆区域施工吗？", "a": "可以，但仅按工作许可证制度执行：使用气体分析仪监测、使用防爆工具、动火作业需单独审批，并配备消防值班岗。"}, {"q": "材料由你们提供还是由业主提供？", "a": "两种方式都可以。由我们自行供应材料时，价格通常更低，并且责任更为集中统一。"}, {"q": "你们会前往其他州施工吗？", "a": "是的，我们在乌兹别克斯坦全境施工。团队采用轮班驻场方式出工，设备运送至施工现场。"}, {"q": "在质保和文件方面提供什么？", "a": "根据工作类型提供12至36个月的质保。文件包括：验收证明、测试报告、涂层厚度测量记录、竣工图纸、材料合格证书。"}]}, "cta": {"label": "10 — 联系方式", "h2a": "您的项目", "h2b": "让我们来探讨", "lead": "请发送图纸或项目说明——我们会结合介质和工况条件，在<b>2个工作日内</b>准备报价方案。现场勘察免费。", "phoneLabel": "电话", "telegramLabel": "Telegram", "telegramValue": "点击发送消息", "emailLabel": "电子邮箱", "addressLabel": "地址", "addressValue": "撒马尔罕州帕赫塔奇区布尔库特", "hoursLabel": "工作时间", "hoursValue": "周一至周六 9:00–18:00 · 施工现场 24/7", "form": {"nameLabel": "您的姓名", "namePh": "您的姓名", "phoneLabel": "电话 *", "phonePh": "+998 __ ___-__-__", "companyLabel": "公司", "companyPh": "公司名称", "serviceLabel": "服务", "servicePlaceholder": "请选择…", "serviceOptions": ["管道安装", "设备安装", "储罐安装", "金属结构", "氩弧焊", "电弧焊", "喷砂处理", "耐化学腐蚀涂层", "工业保温", "脚手架搭设", "衬里（瓷砖/砖）", "其他"], "envLabel": "介质与工况条件", "envPh": "例如：96% H₂SO₄，60°C", "msgLabel": "项目简要说明", "msgPh": "项目、规模、工期…", "submit": "提交申请", "note": "您的信息不会提供给第三方。", "ok": "感谢您！您的申请已收到，我们的经理将尽快与您联系。"}}, "footer": {"tagline": "工业建设与安装", "about": "专注于化工行业设施建设与安装的全流程总承包商，业务覆盖乌兹别克斯坦全境。", "servicesTitle": "服务项目", "servicesLinks": ["管道系统", "设备与储罐安装", "金属结构", "氩弧焊与电弧焊", "涂层与衬里", "保温", "脚手架搭设"], "companyTitle": "公司", "companyLinks": ["关于我们", "项目案例", "常见问题", "联系方式"], "reqTitle": "企业信息", "reqDirectorLabel": "总经理", "rights": "版权所有，保留一切权利。"}} };

  /* ---------- UZ latin -> UZ cyrillic transliteration ---------- */
  const PROTECT = [
    'H₂SO₄', 'HNO₃', 'H₃PO₄', 'NaOH',
    'Pakhtachi Stone Group', 'E-mail',
    'MIG/MAG', 'FRP/GRP', 'C5-I',
    'AISI', 'ISO', 'TIG', 'MMA', 'MIG', 'MAG', 'RDS', 'LOTO', 'FAQ',
    'FRP', 'GRP', 'PVDF', 'PE100', 'PVX', 'HDPE', 'PPU', 'PP',
    'CUI', 'CX', 'C5', 'DFT', '316L', 'duplex', 'Ex', 'Sa',
  ].sort((a, b) => b.length - a.length);

  const PROTECT_RE = new RegExp(
    '(?<![A-Za-z])(?:' + PROTECT.map(t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|') + ')(?![A-Za-z])',
    'g'
  );

  const WORD_OVERRIDES = { bariyer: 'барьер', konveyer: 'конвейер', travleniye: 'травление' };

  const DIGRAPHS = [[/o'/g, 'ў'], [/O'/g, 'Ў'], [/g'/g, 'ғ'], [/G'/g, 'Ғ']];

  const CASE_DIGRAPHS = [
    ['SH', 'Ш'], ['Sh', 'Ш'], ['sh', 'ш'],
    ['CH', 'Ч'], ['Ch', 'Ч'], ['ch', 'ч'],
    ['YA', 'Я'], ['Ya', 'Я'], ['ya', 'я'],
    ['YO', 'Ё'], ['Yo', 'Ё'], ['yo', 'ё'],
    ['YU', 'Ю'], ['Yu', 'Ю'], ['yu', 'ю'],
  ];

  const LETTERS = {
    a: 'а', b: 'б', d: 'д', f: 'ф', g: 'г', h: 'ҳ',
    i: 'и', j: 'ж', k: 'к', l: 'л', m: 'м', n: 'н',
    o: 'о', p: 'п', q: 'қ', r: 'р', s: 'с', t: 'т',
    u: 'у', v: 'в', x: 'х', y: 'й', z: 'з', c: 'ц',
    w: 'в', e: 'е',
  };
  const LETTERS_UP = {};
  for (const k in LETTERS) LETTERS_UP[k.toUpperCase()] = LETTERS[k].toUpperCase();

  function mapLetters(s) {
    let out = '';
    for (const ch of s) out += LETTERS_UP[ch] !== undefined ? LETTERS_UP[ch] : (LETTERS[ch] !== undefined ? LETTERS[ch] : ch);
    return out;
  }

  function transliterateWord(word) {
    const lower = word.toLowerCase();
    if (WORD_OVERRIDES[lower]) {
      const cy = WORD_OVERRIDES[lower];
      return word[0] === word[0].toUpperCase() && word[0] !== word[0].toLowerCase() ? cy[0].toUpperCase() + cy.slice(1) : cy;
    }
    let s = word;
    s = s.replace(/byekt/g, 'бъект').replace(/Byekt/g, 'Бъект');
    for (const [re, rep] of DIGRAPHS) s = s.replace(re, rep);
    s = s.replace(/^YE/, 'Е').replace(/^Ye/, 'Е').replace(/^ye/, 'е');
    for (const [pat, rep] of CASE_DIGRAPHS) s = s.split(pat).join(rep);
    s = s.replace(/'/g, 'ъ');
    s = s.replace(/^E(?=[a-zўғъ]|$)/, 'Э');
    s = s.replace(/^e(?=[a-zA-ZўЎғҒъ]|$)/, 'э');
    return mapLetters(s);
  }

  const MARK_START = 0xE000;
  function uzToCyrillic(text) {
    if (!text) return text;
    const protectedTokens = [];
    const mark = m => { protectedTokens.push(m); return String.fromCodePoint(MARK_START + protectedTokens.length - 1); };
    const masked = text.replace(/<\/?[a-zA-Z][^>]*>/g, mark).replace(PROTECT_RE, mark).replace(/°C/g, mark);
    const converted = masked.replace(/[A-Za-z']+/g, transliterateWord);
    return converted.replace(/[-]/g, ch => protectedTokens[ch.codePointAt(0) - MARK_START]);
  }

  function mapDeep(node, fn) {
    if (typeof node === 'string') return fn(node);
    if (Array.isArray(node)) return node.map(v => mapDeep(v, fn));
    if (node && typeof node === 'object') {
      const out = {};
      for (const k in node) out[k] = mapDeep(node[k], fn);
      return out;
    }
    return node;
  }

  let uzcCache = null;
  function getDict(lang) {
    if (lang === 'uzc') {
      if (!uzcCache) uzcCache = mapDeep(TRANSLATIONS.uz, uzToCyrillic);
      return uzcCache;
    }
    return TRANSLATIONS[lang] || TRANSLATIONS.uz;
  }

  function pathGet(obj, path) {
    return path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), obj);
  }

  const HTML_LANG = { uz: 'uz', uzc: 'uz-Cyrl', ru: 'ru', zh: 'zh-Hans' };
  const LANGS = ['uz', 'uzc', 'ru', 'zh'];
  const STORAGE_KEY = 'psg_lang';

  function detectLang() {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved && LANGS.includes(saved)) return saved;
    } catch (e) {}
    const langs = navigator.languages || [navigator.language || 'uz'];
    for (const l of langs) {
      const base = l.toLowerCase().slice(0, 2);
      if (base === 'ru') return 'ru';
      if (base === 'zh') return 'zh';
      if (base === 'uz') return 'uz';
    }
    return 'uz';
  }

  function apply(lang) {
    const dict = getDict(lang);
    document.documentElement.lang = HTML_LANG[lang] || 'uz';

    const title = pathGet(dict, 'meta.title');
    if (title) document.title = title;
    const desc = document.getElementById('metaDescription');
    const descVal = pathGet(dict, 'meta.description');
    if (desc && descVal) desc.setAttribute('content', descVal);

    document.querySelectorAll('[data-i18n]').forEach(el => {
      const val = pathGet(dict, el.getAttribute('data-i18n'));
      if (typeof val === 'string') el.textContent = val;
    });
    document.querySelectorAll('[data-i18n-html]').forEach(el => {
      const val = pathGet(dict, el.getAttribute('data-i18n-html'));
      if (typeof val === 'string') el.innerHTML = val;
    });
    document.querySelectorAll('[data-i18n-h2]').forEach(el => {
      const key = el.getAttribute('data-i18n-h2');
      const section = pathGet(dict, key);
      if (section && typeof section.h2a === 'string') {
        el.innerHTML = section.h2a + ' <br><em>' + section.h2b + '</em>';
      }
    });
    const line2 = document.getElementById('heroLine2');
    if (line2) {
      const h = pathGet(dict, 'hero');
      if (h) line2.innerHTML = h.line2pre + '<em>' + h.line2em + '</em>';
    }
    document.querySelectorAll('[data-i18n-alt]').forEach(el => {
      const val = pathGet(dict, el.getAttribute('data-i18n-alt'));
      if (typeof val === 'string') el.setAttribute('alt', val);
    });
    document.querySelectorAll('[data-i18n-aria-label]').forEach(el => {
      const val = pathGet(dict, el.getAttribute('data-i18n-aria-label'));
      if (typeof val === 'string') el.setAttribute('aria-label', val);
    });
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
      const val = pathGet(dict, el.getAttribute('data-i18n-placeholder'));
      if (typeof val === 'string') el.setAttribute('placeholder', val);
    });

    document.querySelectorAll('#langSwitch [data-lang]').forEach(btn => {
      btn.classList.toggle('is-active', btn.getAttribute('data-lang') === lang);
      btn.setAttribute('aria-pressed', String(btn.getAttribute('data-lang') === lang));
    });

    if (typeof window.__psgResplit === 'function') window.__psgResplit();
  }

  function setLang(lang) {
    if (!LANGS.includes(lang)) return;
    try { localStorage.setItem(STORAGE_KEY, lang); } catch (e) {}
    apply(lang);
  }

  document.querySelectorAll('#langSwitch [data-lang]').forEach(btn => {
    btn.addEventListener('click', () => setLang(btn.getAttribute('data-lang')));
  });

  apply(detectLang());
})();
